/**
 * Loads the simplified Sri Lanka coastline GeoJSON (generated by
 * scripts/geo/build-terrain.mjs) and projects it into scene coordinates.
 * The same rings were used as constrained edges of the terrain mesh, so the
 * coastline wall built from them meets the land surface exactly.
 */
import { geojsonToProjectedRings, ringsBounds } from '../geography/coordinate-conversion.js';

export async function loadBoundary(loader, url) {
  const geojson = await loader.loadJSON(url);
  const rings = geojsonToProjectedRings(geojson);
  if (!rings.length) throw new Error('Boundary GeoJSON contains no polygons');
  return { geojson, rings, bounds: ringsBounds(rings) };
}
